import { readFile } from "node:fs/promises";

export default function isolateProducer(pi) {
    pi.on("session_start", (_event, ctx) => {
        const options = ctx.getSystemPromptOptions();
        console.log("U12_CONTEXT_READY " + JSON.stringify({
            schema: "funnysharp-native-context-observation/v2",
            sessionId: ctx.sessionManager.getSessionId(),
            systemPrompt: ctx.getSystemPrompt(),
            contextFiles: options.contextFiles?.map(file => file.path) ?? [],
            skills: options.skills?.map(skill => skill.name) ?? [],
            activeTools: pi.getActiveTools(),
            model: { provider: ctx.model?.provider, id: ctx.model?.id }
        }));
    });
    pi.on("before_provider_request", async (event, ctx) => {
        const request = await readFile("request.json", "utf8");
        const payload = {
            ...event.payload,
            input: [
                { role: "developer", content: ctx.getSystemPrompt() },
                { role: "user", content: request }
            ]
        };
        console.log("U12_PRE_BOUNDARY_PROVIDER_PAYLOAD " + JSON.stringify(event.payload));
        console.log("U12_PROVIDER_PAYLOAD " + JSON.stringify(payload));
        return payload;
    });
}
